content:
{
 "cases": [
  {
   "name": "缺少参数",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ]
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "类型错误",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-backup",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ]
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "model_not_allowed"
  },
  {
   "name": "取值越界",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "消息内容包含拦截词",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好，我不能处理拦截词"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "content_filter"
  },
  {
   "name": "max_tokens 大于 4096",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好，我不能处理拦截词"
     }
    ],
    "temperature": 3,
    "max_tokens": 4097
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "invalid_parameter"
  },
  {
   "name": "消息中包含图片",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好，我不能处理拦截词"
     },
     {
      "role": "assistant",
      "content": "图片1"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "image_not_supported"
  },
  {
   "name": "消息中包含拦截词",
   "method": "POST",
   "path": "/v1/chat/completions",
   "auth": "valid",
   "body": {
    "model": "qwen-mini",
    "messages": [
     {
      "role": "user",
      "content": "你好，我不能处理拦截词"
     },
     {
      "role": "assistant",
      "content": "违禁词示例"
     }
    ],
    "temperature": 3
   },
   "raw_body": null,
   "expect_status": 400,
   "expect_code": "content_filter"
  }
 ]
}
